The program finds every statement of the form `name <- value` in the input and runs them in order. The value can be an integer literal or another variable. Any surrounding text is ignored, and the program prints the final values in the requested format.

```python
import re
import sys

def main():
    text = sys.stdin.read()
    env = {}
    pattern = re.compile(r'([A-Za-z_]\w*)\s*<-\s*(-?\d+|[A-Za-z_]\w*)')
    for m in pattern.finditer(text):
        target, src = m.group(1), m.group(2)
        if re.fullmatch(r'-?\d+', src):
            val = int(src)
        else:
            val = env.get(src, 0)
        env[target] = val
    out = []
    for name in ("a", "b", "TMP"):
        out.append(f"{name} ?= {env.get(name, 0)};")
    print(" ".join(out))

if __name__ == "__main__":
    main()
